style.css:
@-moz-document url("https://www.satchelone.com/todos/upcoming") {
/* General Background and Text */
  body, html {
    background-color: #121212 !important; /* Dark background */
    color: #e0e0e0 !important; /* Light text */
  }

  /* Links */
  a {
    color: #1e90ff !important; /* Light blue links */
  }

  /* Buttons */
  button, input[type="submit"], input[type="button"] {
    background-color: #333333 !important; /* Dark button background */
    color: #ffffff !important; /* White text */
    border: 1px solid #555555 !important; /* Border */
  }

  /* Input Fields */
  input, textarea, select {
    background-color: #333333 !important; /* Dark background */
    color: #ffffff !important; /* Light text */
    border: 1px solid #555555 !important; /* Border */
  }

  /* Navbar, Footer, and Headers */
  header, .navbar, footer {
    background-color: #1e1e1e !important; /* Dark navbar/footer */
    color: #d4d4d4 !important; /* Light text */
  }

  /* To-Do List Panels */
  .panel, .widget, .todo-item {
    background-color: #2b2b2b !important; /* Dark panel background */
    color: #d4d4d4 !important; /* Light panel text */
    border: 1px solid #444444 !important; /* Border */
  }

  /* Tables or Lists */
  table, .list-container {
    background-color: #2a2a2a !important; /* Dark list background */
    color: #e0e0e0 !important; /* Light text */
  }

  /* Modals */
  .modal {
    background-color: #2e2e2e !important; /* Dark modal background */
    color: #e0e0e0 !important; /* Modal text */
  }

  /* Hover Effects */
  a:hover, button:hover, .todo-item:hover {
    background-color: #444444 !important; /* Hover background */
    color: #ffffff !important; /* Hover text */
  }

  /* Shadows and Borders */
  * {
    box-shadow: none !important;
    border-color: #444444 !important;
  }
}
